/** @format */

import { AsyncHandler } from "../Utils/AsyncHandler.js";
import { ApiError } from "../Utils/ApiError.js";
import { ApiResponse } from "../Utils/ApiResponse.js";
import { Document } from "../Models/document.model.js";
import { Conversation } from "../Models/conversation.model.js";
import { Message } from "../Models/message.model.js";
import { v4 as uuidv4 } from "uuid";
import axios from "axios";
import mongoose from "mongoose";

const uploadDocument = AsyncHandler(async (req, res) => {
  const { conversationId } = req.body;

  if (!req.file) {
    throw new ApiError(400, "No file uploaded.");
  }
  if (!mongoose.isValidObjectId(conversationId)) {
    throw new ApiError(400, "Invalid conversation ID");
  }
  const conversation = await Conversation.findOne({
    _id: conversationId,
    user: req.user._id,
  });
  if (!conversation) {
    throw new ApiError(404, "Conversation not found.");
  }

  const newDocument = await Document.create({
    user: req.user._id,
    conversation: conversationId,
    fileName: req.file.originalname,
    s3Url: req.file.location,
    fileType: req.file.mimetype,
    status: "processing",
    pineconeNamespace: `doc-${uuidv4()}`,
  });

  const systemMessage = await Message.create({
    conversation: conversationId,
    role: "system",
    content: `File uploaded: ${newDocument.fileName}. Processing...`,
    messageType: "document_notification",
    document: newDocument._id,
  });

  axios
    .post(`${process.env.PYTHON_SERVICE_URL}/process-document`, {
      documentId: newDocument._id,
      s3Url: newDocument.s3Url,
      pineconeNamespace: newDocument.pineconeNamespace,
    })
    .catch((err) => {
      console.error(
        "Failed to trigger Python processing service:",
        err.message
      );
    });

  await Conversation.findByIdAndUpdate(conversationId, {
    $push: { documents: newDocument._id },
  });

  return res.status(201).json(
    new ApiResponse(
      201,
      {
        document: newDocument,
        message: systemMessage,
      },
      "File uploaded and processing started."
    )
  );
});

const updateDocumentStatus = AsyncHandler(async (req, res) => {
  const { documentId } = req.params;
  const { status } = req.body;

  if (!["processed", "failed"].includes(status)) {
    throw new ApiError(400, "Invalid status provided.");
  }

  const document = await Document.findByIdAndUpdate(
    documentId,
    { $set: { status: status } },
    { new: true }
  );

  if (!document) {
    throw new ApiError(404, "Document not found");
  }

  return res
    .status(200)
    .json(new ApiResponse(200, document, "Document status updated."));
});

export { uploadDocument, updateDocumentStatus };
