/** @format */

import { Router } from "express";
import {
  uploadDocument,
  updateDocumentStatus,
} from "../Controllers/document.controller.js";
import { verifyJWT } from "../Middlewares/auth.middleware.js";
import { upload } from "../Middlewares/multer.middleware.js"; // IMPORTANT: You need to create this middleware

const router = Router();

// Apply JWT authentication to all document routes
router.use(verifyJWT);

/**
 * @route POST /api/v1/documents/upload
 * @description This route handles file uploads.
 * The `upload.single("document")` middleware processes the file first.
 * "document" should be the name of the file field in your form-data request from the frontend.
 */
router.route("/upload").post(
  upload.single("document"), // Multer middleware for a single file upload
  uploadDocument
);

/**
 * @route PATCH /api/v1/documents/:documentId/status
 * @description This is a webhook endpoint for your Python AI service to call
 * back to when it has finished processing a document.
 * It's protected to ensure only authenticated services/users can call it.
 */
router.route("/:documentId/status").patch(updateDocumentStatus);

export default router;
