/** @format */

import { Router } from "express";
import {
  getAllConversations,
  createConversation,
  getConversationById,
  deleteConversation,
} from "../Controllers/conversation.controller.js";
import { verifyJWT } from "../Middlewares/auth.middleware.js";

const router = Router();

// Apply JWT authentication to all conversation routes
router.use(verifyJWT);

// Routes for getting all conversations and creating a new one
router.route("/").get(getAllConversations).post(createConversation);

// Routes for a specific conversation by its ID
router
  .route("/:conversationId")
  .get(getConversationById)
  .delete(deleteConversation);

export default router;
